Read the cached A:C values and identify column-A rows matching `400-...-A`. For each match, mark rows from that row through the row before the next column-A value starting with `400-` for deletion. Write the remaining rows compacted into A1:C26, leaving trailing cells empty.

```python
import shutil
import re
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

max_row = max(vws.max_row or 0, 26)
max_col = 3

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

rows = []
for r in range(1, max_row + 1):
    rows.append([clean(vws.cell(row=r, column=c).value) for c in range(1, max_col + 1)])

def is_target(v):
    return isinstance(v, str) and re.fullmatch(r"400-.*-A", v) is not None

def is_400(v):
    return isinstance(v, str) and v.startswith("400-")

delete = set()
for i, row in enumerate(rows, start=1):
    if is_target(row[0]):
        next_i = None
        for j in range(i + 1, max_row + 1):
            if is_400(rows[j - 1][0]):
                next_i = j
                break
        end = next_i - 1 if next_i is not None else max_row
        for k in range(i, end + 1):
            delete.add(k)

kept = [rows[i - 1] for i in range(1, max_row + 1) if i not in delete]

for r in range(1, max_row + 1):
    for c in range(1, max_col + 1):
        if r <= len(kept):
            ws.cell(row=r, column=c).value = kept[r - 1][c - 1]
        else:
            ws.cell(row=r, column=c).value = None

print("deleted rows:", sorted(delete))
print("kept rows:", len(kept))
print("first kept:", kept[0] if kept else None)
print("row6:", kept[5] if len(kept) > 5 else None)

wb.save(OUT)
